"""Stretches of opening hours that no worked span covers."""

from typing import Iterable, List

from hourglass.parsing import format_span
from hourglass.models import Span
from hourglass.merging import merge_spans

def _check_inside(spans: List[Span], opening: Span) -> None:
    for span in spans:
        early = span.start < opening.start
        late = span.end > opening.end
        if early or late:
            message = "span is outside opening hours"
            raise ValueError(message)

def _between(
    spans: List[Span], opening: Span
) -> List[Span]:
    starts = [opening.start] + [span.end for span in spans]
    ends = [span.start for span in spans] + [opening.end]
    pairs = zip(starts, ends)
    return [Span(s, e) for s, e in pairs if s < e]

# ---
def uncovered_spans(
    worked: Iterable[Span], opening: Span
) -> List[Span]:
    """Opening hours no worked span covers, in order."""
    spans = merge_spans(worked)
    _check_inside(spans, opening)
    return _between(spans, opening)

def _label(gap: Span) -> str:
    return f"gap {format_span(gap)} ({gap.minutes} min)"

# ---
def find_gaps(
    worked: Iterable[Span], opening: Span
) -> List[str]:
    """Text labels such as gap 12:00-13:00 (60 min)."""
    gaps = uncovered_spans(worked, opening)
    return [_label(gap) for gap in gaps]

