import unittest

from hourglass.models import Span
from hourglass.gaps import find_gaps, uncovered_spans

OPENING = Span(540, 1020)

class UncoveredSpanTests(unittest.TestCase):
    # ---
    def test_nobody_working_is_one_gap(self):
        self.assertEqual(
            uncovered_spans([], OPENING), [OPENING]
        )

    # ---
    def test_full_cover_leaves_nothing(self):
        worked = [Span(540, 1020)]
        self.assertEqual(
            uncovered_spans(worked, OPENING), []
        )

    # ---
    def test_gap_between_shifts(self):
        worked = [Span(540, 720), Span(780, 1020)]
        self.assertEqual(
            uncovered_spans(worked, OPENING),
            [Span(720, 780)]
        )

    # ---
    def test_gaps_at_both_ends(self):
        worked = [Span(600, 900)]
        self.assertEqual(
            uncovered_spans(worked, OPENING),
            [Span(540, 600), Span(900, 1020)]
        )

    # ---
    def test_overlaps_and_order_are_ignored(self):
        worked = [
            Span(600, 660), Span(540, 570), Span(630, 720)
        ]
        self.assertEqual(
            uncovered_spans(worked, OPENING),
            [Span(570, 600), Span(720, 1020)]
        )

    # ---
    def test_span_outside_opening_raises(self):
        with self.assertRaises(ValueError):
            uncovered_spans([Span(480, 600)], OPENING)
        with self.assertRaises(ValueError):
            uncovered_spans([Span(900, 1080)], OPENING)

class FindGapsTests(unittest.TestCase):
    # ---
    def test_no_gaps_gives_empty_list(self):
        worked = [Span(540, 1020)]
        self.assertEqual(find_gaps(worked, OPENING), [])

    # ---
    def test_label_for_one_gap(self):
        worked = [Span(540, 720), Span(780, 1020)]
        self.assertEqual(
            find_gaps(worked, OPENING),
            ["gap 12:00-13:00 (60 min)"]
        )

    # ---
    def test_label_for_each_gap(self):
        worked = [
            Span(600, 660), Span(540, 570), Span(630, 720)
        ]
        self.assertEqual(
            find_gaps(worked, OPENING),
            [
                "gap 09:30-10:00 (30 min)",
                "gap 12:00-17:00 (300 min)"
            ]
        )

    # ---
    def test_span_outside_opening_raises(self):
        with self.assertRaises(ValueError):
            find_gaps([Span(480, 600)], OPENING)
